async function secretKey(env){const raw=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`myts-secret:${clean(env.ADMIN_KEY)}`));return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);}
