async function decryptSecret(env,value){const [iv,cipher]=String(value||'').split('.');if(!iv||!cipher)return '';try{const key=await secretKey(env),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(iv)},key,b64ToBytes(cipher));return new TextDecoder().decode(plain);}catch{throw new ApiError('Stored TeamSnap credentials cannot be opened. Reconnect TeamSnap from /admin.',409,'teamsnap_reconnect_required');}}

