async function readUnifiedGeneration(env,family){for(let attempt=0;attempt<2;attempt++){const ds=await unifiedDataset(env,family);if(!ds)return {ds:null,rows:[]};const result=await env.DB.prepare('SELECT game_id,data_json,updated_at FROM trace_match_payloads WHERE family_key=? AND generation_id=? ORDER BY game_date,game_id').bind(family,ds.active_generation).all(),current=await unifiedDataset(env,family);if(current?.active_generation===ds.active_generation){if(Number(ds.match_count||0)>(result.results||[]).length)throw new ApiError('The saved Trace dataset is incomplete. Reimport your Trace backup from Account.',409,'trace_snapshot_incomplete');return {ds,rows:result.results||[]};}}throw new ApiError('Trace changed during this read. Saved data is retained; retrying automatically.',409,'trace_snapshot_changed');}

