async function tenantStorageKey(owner,publicKey){const familyHash=await sha256Hex(`team-family:${clean(publicKey)}`);return `u:${clean(owner).slice(0,32)}:${familyHash.slice(0,32)}`;}
async function connection(env,key){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=?').bind(key).first();}
async function ownedConnection(env,key,owner){return env.DB.prepare('SELECT * FROM trace_connections WHERE teamsnap_key=? AND owner_hash=?').bind(key,owner).first();}
async function authSession(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_sessions WHERE owner_hash=?').bind(owner).first();if(row?.cookie_header)row.cookie_header=await decryptSecret(env,row.cookie_header);return row;}
async function pendingAuth(env,owner){const row=await env.DB.prepare('SELECT * FROM trace_auth_pending WHERE owner_hash=?').bind(owner).first();if(row?.guest_cookie)row.guest_cookie=await decryptSecret(env,row.guest_cookie);return row;}
async function tenantKeyFor(env,owner,publicKey){return tenantStorageKey(owner,clean(publicKey));}

async function enforceRateLimit(env,bucket,limit,windowMs=TRACE_RATE_WINDOW_MS){const slot=Math.floor(Date.now()/windowMs),key=`${bucket}:${slot}`,expiresAt=(slot+1)*windowMs,row=await env.DB.prepare(`INSERT INTO trace_rate_limits(bucket,hits,expires_at) VALUES(?,1,?) ON CONFLICT(bucket) DO UPDATE SET hits=trace_rate_limits.hits+1,expires_at=excluded.expires_at RETURNING hits`).bind(key,expiresAt).first();if(Number(row?.hits||0)>limit)throw new ApiError('Too many attempts. Try again later.',429,'rate_limited');}

function tsCollectionObjects(payload){return(payload?.collection?.items||[]).map(item=>{const o={};for(const d of item.data||[])if(d?.name)o[d.name]=d.value;for(const l of item.links||[])if(l.rel&&!o[`_link_${l.rel}`])o[`_link_${l.rel}`]=l.href;o._href=item.href||item.links?.find(l=>l.rel==='self')?.href||null;return o;});}
function tsCollectionLink(payload,rel){return payload?.collection?.links?.find(l=>l.rel===rel)?.href||payload?.collection?.items?.flatMap(i=>i.links||[]).find(l=>l.rel===rel)?.href||null;}
function teamSnapRetryDelay(value){
  const seconds=Number(value),date=Date.parse(value||'');
  return value&&Number.isFinite(seconds)?Math.max(0,seconds*1000):Number.isFinite(date)?Math.max(0,date-Date.now()):0;
}
function diagnosticErrorText(value){
  return String(value||'').replace(/https?:\/\/[^\s]+/gi,'[url]').replace(/Bearer\s+[^\s]+/gi,'Bearer [redacted]').replace(/((?:token|secret|password|cookie|authorization)\s*[:=]\s*)[^\s,;]+/gi,'$1[redacted]').slice(0,500);
}
function sourceTransportError(cause,source,endpoint,timedOut=false){
  const raw=String(cause?.message||''),limit=/too many subrequests|subrequest.*limit|cpu.*limit|memory.*limit/i.test(raw),cancelled=/cancel|connection.*limit/i.test(raw);
  const kind=/illegal invocation|incorrect.*this reference/i.test(raw)?'runtime_invocation':limit?'worker_limit':timedOut?'timeout':cancelled?'cancelled':'network';
  const label=source==='teamsnap'?'TeamSnap':'GotSport';
  const message=kind==='runtime_invocation'?`An internal app error prevented the ${label} request.`:limit?`myTS reached a Worker execution limit while updating ${label}.`:timedOut?`${label} request timed out.`:cancelled?`${label} request was cancelled by the runtime.`:`${label} transport failed.`;
  const error=new ApiError(message+' Saved data is retained.',502,`${source}_${kind}`);
  error.source=source;error.endpoint=endpoint;error.retryable=kind!=='runtime_invocation';error.failure_kind=kind;error.exception_name=String(cause?.name||'Error').slice(0,60);error.exception_message=diagnosticErrorText(raw);
  return error;
}
async function tsJson(url,token,timeoutMs=10000){
  url=tsUrl(url).href;
  const endpoint=new URL(url).pathname;
  for(let attempt=0;attempt<1;attempt++){
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),Math.max(1,timeoutMs));
    let error;
    try{
      const res=await fetch(url,{headers:{Authorization:`Bearer ${token}`,Accept:'application/vnd.collection+json, application/json'},cache:'no-store',redirect:'manual',signal:controller.signal});
      const retryAfter=teamSnapRetryDelay(res.headers.get('retry-after'));
      const payload=await res.json().catch(e=>{if(controller.signal.aborted)throw e;return null;});
      if(res.ok&&Array.isArray(payload?.collection?.items)&&!payload.collection.error)return payload;
      if(res.status===401)error=new ApiError('TeamSnap authorization expired. Reconnect TeamSnap from /admin.',401,'teamsnap_auth_expired');
      else if([429,502,503,504].includes(res.status))error=new ApiError(`TeamSnap service returned HTTP ${res.status} at ${endpoint}. Saved data is retained; myTS will retry automatically.`,502,'teamsnap_upstream_unavailable');
      else error=new ApiError(payload?.collection?.error?.message||`TeamSnap returned ${res.ok?'an invalid response':`HTTP ${res.status}`} at ${endpoint}.`,502,'teamsnap_request_failed');
      error.source='teamsnap';error.upstream_status=res.status;error.endpoint=endpoint;error.retry_after_ms=retryAfter;
      error.retryable=[429,502,503,504].includes(res.status);
    }catch(e){
      error=sourceTransportError(e,'teamsnap',endpoint,controller.signal.aborted);
    }finally{clearTimeout(timer)}
    throw error;
  }
}

function mergeTsObjects(base,extra){const map=new Map();for(const x of base||[])if(x?.id!=null)map.set(String(x.id),{...x});for(const x of extra||[]){if(x?.id==null)continue;const k=String(x.id);map.set(k,{...(map.get(k)||{}),...x});}return[...map.values()];}
function eventDetailCandidates(rows,limit=36){const n=Date.now(),past=120*86400000,future=240*86400000;return(rows||[]).filter(e=>e?.id!=null).map(e=>{const raw=e.start_date||e.start_at||e.starts_at||e.date,t=Date.parse(raw||'');return{e,t:Number.isFinite(t)?t:null};}).filter(x=>x.t===null||(x.t>=n-past&&x.t<=n+future)).sort((a,b)=>Math.abs((a.t??n)-n)-Math.abs((b.t??n)-n)).slice(0,limit).map(x=>x.e);}
function pick(o,keys){const z={};for(const k of keys)if(o?.[k]!==undefined)z[k]=o[k];return z;}
function sanitizeTeam(t){return pick(t,['id','name','team_name','label','season_name','season_label','season_title','season','season_start_date','season_end_date','start_date','end_date','starts_at','ends_at','updated_at','modified_at','created_at','created_date','created','is_archived','archived','is_retired','retired','status','location_name','location','city','state','state_code','zip','postal_code','time_zone','timezone','time_zone_name','browser_time_zone']);}
function sanitizeEvent(e){return pick(e,['id','name','formatted_title','label','type','is_game','start_date','start_at','starts_at','date','location_id','opponent_id','location_name','opponent_name','season_phase','season_phase_name','phase_name','event_phase','points_for_team','points_for_opponent','team_score','opponent_score','score_for','score_against','result','results','home_or_away','home_away','location_type','is_home','is_away','is_canceled','is_cancelled','canceled','cancelled','is_postponed','is_rescheduled','status','event_status','notes','additional_location_details','arrival_date','minutes_to_arrive_early','uniform','updated_at','is_availability_enabled','availability_enabled','tracks_availability','is_availability_tracking_enabled']);}
function sanitizeMember(m){return pick(m,['id','first_name','last_name','name','label','type','member_type','role','position','position_name','sport_position_name','position_label','jersey_number','jersey','number','uniform_number','jersey_no','uniform_no','is_non_player','is_manager','is_owner','is_coach','is_player','is_active','active_status']);}
function sanitizeLocation(x){return pick(x,['id','name','label','address','city','state','state_code','zip','postal_code']);}function sanitizeOpponent(x){return pick(x,['id','name','label']);}function sanitizeAvailability(x){return pick(x,['id','event_id','member_id','status_code']);}
function sanitizeResource(resource,rows){const fn={events:sanitizeEvent,members:sanitizeMember,locations:sanitizeLocation,opponents:sanitizeOpponent,availabilities:sanitizeAvailability}[resource]||((x)=>x);return(rows||[]).map(fn);}
// Observe source fields before allowlisting. Owner diagnostics only; no personal record values.
function tsObserveFields(job,resource,payload,rows,endpoint){
 const audit=job.field_audit||(job.field_audit={version:1,started_at:now(),resources:{}});
 const entry=audit.resources[resource]||(audit.resources[resource]={pages:0,rows:0,fields:{},relations:[],endpoints:[]});
 entry.pages++;entry.rows+=rows.length;
 const path=new URL(endpoint).pathname.replace(/\/\d+(?=\/|$)/g,'/:id');if(!entry.endpoints.includes(path))entry.endpoints.push(path);
 for(const link of payload?.collection?.links||[]){const rel=String(link?.rel||'');if(rel&&!entry.relations.includes(rel))entry.relations.push(rel);}
 for(const row of rows){
  const kept=resource==='teams'?sanitizeTeam(row):resource==='account'?{}:sanitizeResource(resource,[row])[0];
  for(const [key,value] of Object.entries(row)){
   if(key==='_href'||key.startsWith('_link_'))continue;
   const f=entry.fields[key]||(entry.fields[key]={seen:0,populated:0,types:[],retained:Object.hasOwn(kept,key)});
   f.seen++;if(value!==null&&value!==undefined&&value!=='')f.populated++;
   const type=value===null?'null':Array.isArray(value)?'array':typeof value;if(!f.types.includes(type))f.types.push(type);
   // Examples limited to match logistics; never copy member/contact/account/notes data.
   if(resource==='events'&&/^(uniform|uniform_name|uniform_color|arrival_time|arrival_date|end_date|duration_in_minutes)$/.test(key)&&['string','number','boolean'].includes(type)&&value!==''){
    const sample=String(value).slice(0,120);f.examples||=[];if(f.examples.length<3&&!f.examples.includes(sample))f.examples.push(sample);
   }
  }
 }
 audit.updated_at=now();
}

function discoverTsTeamUrls(payload,me){const urls=new Set(),add=l=>{if(!l?.href)return;const rel=clean(l.rel).toLowerCase();let u;try{u=new URL(l.href);}catch{return;}if(!tsCatalogLink(u.href)&&/\/teams(?:\/|$)/i.test(u.pathname)&&['teams','active_teams','archived_teams','past_teams','retired_teams','team_history'].includes(rel))urls.add(u.toString());};for(const l of payload?.collection?.links||[])add(l);for(const item of payload?.collection?.items||[])for(const l of item.links||[])add(l);for(const[k,v]of Object.entries(me||{}))if(k.startsWith('_link_')&&v)add({rel:k.slice(6),href:v});return[...urls];}
// GotSport: three public JSON contracts, verified against captured responses.
// Team ID -> event + registration + bracket -> schedule group -> full flight.
const GOTSPORT_CONTRACT = 'gotsport-json-v1';
const GOTSPORT_DEFAULT_TEAM_ID = '212707';
const GOTSPORT_DISCOVERY_MS = 12 * 60 * 60 * 1000;
const GOTSPORT_WEEK_MS = 3 * 60 * 60 * 1000;
const GOTSPORT_DAY_MS = 60 * 60 * 1000;
const GOTSPORT_RETRY_MS = 15 * 60 * 1000;
const GOTSPORT_MAX_REQUESTS = 10;
const GOTSPORT_DATA_REVISION = 'publication-v4-history';
function gsDisplayName(name, club) {
  name=clean(name);club=clean(club);if(!club||!name)return name||club;
  const a=club.split(/\s+/),b=name.split(/\s+/),norm=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');
  if(norm(name).startsWith(norm(club)))return name;
  let shared=0;while(shared<Math.min(a.length,b.length)&&norm(a[shared])===norm(b[shared]))shared++;
  return [...a,...b.slice(shared)].join(' ');
}
async function gsTeamProfile(env,id,runtime=gsRuntime()){
 id=gsId(id);if(!id)throw new ApiError('Invalid team identity.',400);
 const read=()=>env.DB.prepare('SELECT * FROM gotsport_team_profiles WHERE team_id=?').bind(id).first();
 let row=await read();if(!row){await env.DB.prepare('INSERT OR IGNORE INTO gotsport_team_profiles(team_id) VALUES(?)').bind(id).run();row=await read();}const publicValue=()=>({...safeJsonParse(row.profile_json,{}),id,team_id:id,state:row.error?'refresh_failed':Number(row.lease_until)>runtime.at?'updating':safeJsonParse(row.profile_json,{}).logo?'ready':'missing_logo',error:row.error||null,next_at:Math.max(Number(row.next_at)||0,Number(row.lease_until)||runtime.at+60000)});
 if(runtime.at<row.next_at||runtime.at<row.lease_until)return publicValue();
 const lease=await env.DB.prepare('UPDATE gotsport_team_profiles SET lease_until=? WHERE team_id=? AND next_at<=? AND lease_until<=?').bind(runtime.at+30000,id,runtime.at,runtime.at).run();if(!lease.meta?.changes)return publicValue();
 try{const raw=await gsFetchJson('/team_ranking_data/team_details',{team_id:id},runtime);if(gsId(raw.id)!==id)throw gsFail('Team profile identity did not match.','gotsport_team_identity');
 const profile={id,team_id:id,name:gsDisplayName(raw.team_name||raw.name,raw.club_name),club_name:clean(raw.club_name),logo:gsLogoPath(raw.image||raw.team_logo_url_full)};
 if(!profile.name)throw gsFail('Team profile has no name.','gotsport_team_identity');
 await env.DB.prepare('UPDATE gotsport_team_profiles SET profile_json=?,next_at=?,lease_until=0,error=NULL WHERE team_id=? AND lease_until=?').bind(JSON.stringify(profile),runtime.at+7*86400000,id,runtime.at+30000).run();
 }catch(e){await env.DB.prepare('UPDATE gotsport_team_profiles SET next_at=?,lease_until=0,error=? WHERE team_id=? AND lease_until=?').bind(runtime.at+300000,clean(e.message),id,runtime.at+30000).run();}
 row=await read();return publicValue();
}
async function readTeamKits(env,family){const rows=await env.DB.prepare('SELECT season,kits_json FROM team_kit_overrides WHERE family_key=?').bind(family).all();return Object.fromEntries((rows.results||[]).map(r=>[r.season,safeJsonParse(r.kits_json,[])]));}
function validateSeasonKits(kits){
 if(!Array.isArray(kits)||kits.length>30)throw new ApiError('Use up to 30 kits.',400);
 const seen=new Set();return kits.map(k=>{const name=typeof k?.name==='string'?k.name.trim().replace(/\s+/g,' '):'',color=typeof k?.color==='string'?k.color.trim().toLowerCase():'';
 if(!name||name.length>80||color&&!/^#[0-9a-f]{6}$/.test(color))throw new ApiError('Enter a kit name and an optional six-digit hex color.',400);
 const key=name.toLowerCase();if(seen.has(key))throw new ApiError('Each kit name must be unique.',400);seen.add(key);return {name,color};});
}
async function saveTeamKits(request,env,url){
 const family=clean(url.searchParams.get('key')),season=Number(url.searchParams.get('season'));
 if(!keyOk(family)||!Number.isInteger(season)||season<1900||season>2200)throw new ApiError('Choose a team and season.',400);
 const team=await env.DB.prepare('SELECT dataset_id FROM app_datasets WHERE family_key=?').bind(family).first();if(!team)throw new ApiError('Team not found.',404);
 if(request.method==='DELETE')await env.DB.prepare('DELETE FROM team_kit_overrides WHERE family_key=? AND season=?').bind(family,season).run();
 else if(request.method==='PUT'){const body=await bodyJson(request),kits=validateSeasonKits(body.kits);await env.DB.prepare('INSERT INTO team_kit_overrides(family_key,season,kits_json) VALUES(?,?,?) ON CONFLICT(family_key,season) DO UPDATE SET kits_json=excluded.kits_json').bind(family,season,JSON.stringify(kits)).run();}
 else throw new ApiError('Method not allowed.',405);
 return json({kit_overrides:await readTeamKits(env,family)});
}
async function teamLogoOverrides(env){const rows=await env.DB.prepare('SELECT team_id,revision FROM team_logo_overrides').all();return Object.fromEntries((rows.results||[]).map(r=>[r.team_id,`/api/team-logo?team_id=${r.team_id}&v=${r.revision}`]));}
