function splitSetCookie(raw){
  const s=clean(raw);if(!s)return[];
  return s.split(/,(?=\s*[^;,=\s]+=[^;,]*)/g).map(x=>x.trim()).filter(Boolean);
}
function setCookieLines(headers){
  try{if(typeof headers.getSetCookie==='function'){const x=headers.getSetCookie();if(Array.isArray(x)&&x.length)return x;}}catch{}
  try{if(typeof headers.getAll==='function'){const x=headers.getAll('Set-Cookie');if(Array.isArray(x)&&x.length)return x;}}catch{}
  return splitSetCookie(headers.get('set-cookie'));
}
function cookieFromResponse(res,name='PHPSESSID'){
  const prefix=`${name}=`.toLowerCase();
  for(const line of setCookieLines(res.headers)){const first=line.split(';',1)[0].trim();if(first.toLowerCase().startsWith(prefix)){const value=first.slice(prefix.length);if(value)return `${name}=${value}`;}}
  return '';
}
async function traceFetch(url,{method='GET',cookie='',body=null,headers={},signal}={}){
  const h=new Headers({Accept:'application/json, text/plain, */*',Origin:TRACE_APP,Referer:`${TRACE_APP}/`,...headers});
  if(cookie)h.set('Cookie',cookie);
  return fetch(url,{method,headers:h,body,redirect:'follow',signal});
}
async function traceJson(url,opts={}){
  const res=await traceFetch(url,opts);let text='';try{text=await res.text();}catch(e){throw e;}let payload={};if(text){try{payload=JSON.parse(text);}catch{payload={raw:text.slice(0,1000)};}}
  return {res,payload};
}
async function newTraceGuestCookie(){
  try{
    const fd=new FormData(),res=await traceFetch(`${TRACE_TEAMS}/users/self/logout`,{method:'POST',body:fd});
    return cookieFromResponse(res)||'';
  }catch{return '';}
}
function findTraceUserId(value,depth=0){
  if(value==null||depth>8)return '';
  if(typeof value==='string'){const q=value.match(/[?&]user_id=(\d+)/i);return q?.[1]||'';}
  if(Array.isArray(value)){for(const x of value){const id=findTraceUserId(x,depth+1);if(id)return id;}return '';}
  if(typeof value!=='object')return '';
  for(const [k,v] of Object.entries(value)){if(/^(user_id|userId)$/i.test(k)&&/^\d+$/.test(clean(v)))return clean(v);}
  for(const [k,v] of Object.entries(value)){if(/user/i.test(k)){const id=findTraceUserId(v,depth+1);if(id)return id;}}
  for(const v of Object.values(value)){const id=findTraceUserId(v,depth+1);if(id)return id;}
  return '';
}
async function traceUserIdForEmail(email){
  const {res,payload}=await traceJson(`${TRACE_USER_LOOKUP}?email=${encodeURIComponent(email)}`);
  if(!res.ok||payload?.success===false)throw new ApiError(traceMessage(payload,'Trace could not find an account for that email.'),res.status>=400&&res.status<500?400:502,'trace_user_lookup_failed');
  const uid=clean(payload?.data?.id||payload?.data?.user_id||payload?.user_id);
  if(!/^\d+$/.test(uid))throw new ApiError('Trace could not identify the account for that email.',400,'trace_user_lookup_missing');
  return uid;
}
