function radarNames(game){const v=(game?.moments||[]).filter(m=>m?.type==='FullGameVideo').sort((a,b)=>(a.half||0)-(b.half||0)),out=[];for(const m of v)if(m.dynamic_jfile)out.push({half:Number(m.half)||out.length+1,name:clean(m.dynamic_jfile),base_path:clean(m.base_path)});if(!out.length)out.push({half:1,name:'radar1_dynamic.json'},{half:2,name:'radar2_dynamic.json'});return out;}
function safeTraceAsset(path,base=TRACE_APP){try{const u=new URL(path,base);if(u.protocol!=='https:'||!(u.hostname==='traceup.com'||u.hostname.endsWith('.traceup.com')))return'';return u.href;}catch{return'';}}
function radarBases(game,entry,teamSlug){const out=[];for(const b of[entry?.base_path,game?.base_path]){const u=safeTraceAsset(String(b||'').replace(/\/?$/,'/'),TRACE_APP);if(u)out.push(u);}for(const region of['us-west-1','us-west-2','us-east-1'])for(const api of['qaapi','api'])out.push(`${TRACE_APP}/${region}/soccer/${api}/teams/${encodeURIComponent(teamSlug)}/games/${encodeURIComponent(teamSlug)}-${game.game_id}/`);for(const api of['qaapi','api'])out.push(`${TRACE_APP}/${api}/teams/${encodeURIComponent(teamSlug)}/games/${encodeURIComponent(teamSlug)}-${game.game_id}/`);return[...new Set(out)];}
