  if(teams.length)statements.push(env.DB.prepare(`DELETE FROM gotsport_directory_teams WHERE source_key=? AND team_id NOT IN (SELECT json_extract(value,'$.team_id') FROM json_each(?)) AND EXISTS(SELECT 1 FROM gotsport_directory_jobs WHERE id=? AND lease_token=?)`).bind(job.id,JSON.stringify(teams),job.id,job.lease_token),gsDirectoryEvidence(env,job.id,teams,at,String(at),job),gsDirectoryAliases(env,teams,job));
  updated={...data,team_count:teams.length,publication:teams.length?'published':'awaiting_schedule'};next=gsDirectoryNext(data.event,at,teams.length>0);
