const GOTSPORT_HISTORY_FRESH_MS=5*60000,GOTSPORT_SCORE_CHECK_MS=60000;
function gsBrowseDay(value,at=Date.now()){const day=gsDay(value||gsStamp(at).slice(0,10));if(Math.abs(Date.parse(day+'T12:00:00Z')-at)>36*3600000)throw new ApiError('Invalid results date.',400);return day}
