async function gsBrowseRecent(env,row,runtime,day,force=false){
 let events=safeJsonParse(row.events_json,[]),meta=safeJsonParse(row.meta_json,{}),checked=0;
 const today=gsTodayMatches(events,day);if(!today.length)return {events,meta,checked};
 const entries=new Map();
 for(const match of today){
  let details=meta[match.event_id];
  if(!details){details=gsEventDetails(await gsFetchJson('/event_ranking_data/event_details',{event_id:match.event_id},runtime),match.event_id);meta[match.event_id]=details;}
  const groups=gsResolveMatchGroups(details,[match]);
  for(const group of groups)entries.set(match.event_id+':'+group.id,{details,group,eventId:match.event_id});
 }
 for(const {details,group,eventId} of entries.values()){
  const seeds=events.filter(m=>m.event_id===eventId&&group.brackets.some(b=>b.id===m.bracket_id)),pending=seeds.some(m=>gsTodayMatches([m],day).length&&(m.home_score==null||m.away_score==null));
  const result=await gsSharedFlight(env,eventId,group,runtime,pending?GOTSPORT_SCORE_CHECK_MS:GOTSPORT_HISTORY_FRESH_MS,force);
  if(result.sync_error)throw gsFail(safeJsonParse(result.sync_error,{}).message||'Recent results could not be updated.','gotsport_recent_results');
  if(!result.checked_at||result.checked_at<Date.parse(row.last_success_at||''))continue;
  const entry={event_id:eventId,details,registration_ids:gsUnique(seeds.map(m=>m.event_team_id)),schedule_ids:gsUnique(seeds.map(m=>m.schedule_id))};
  const updates=gsFlight(safeJsonParse(result.matches_json,[]),row.team_id,entry,group,seeds).filter(m=>m.is_game),byId=new Map(updates.map(m=>[m.match_id,m]));
  events=events.map(m=>byId.has(m.match_id)?{...m,...byId.get(m.match_id)}:m);
  for(const m of updates)if(!events.some(x=>x.match_id===m.match_id))events.push(m);
  checked=Math.max(checked,result.checked_at);
 }
 return {events,meta,checked};
}
