 const feed=saved||{rankings_team_id:teamId,calendar_name:row.team_name||'',source_meta_json:'{}',events_json:'[]'};
 const result=await collectGotSport(env,feed,{at:runtime.at,runtime});
 meta.dashboard={rankings_team_id:teamId,calendar_name:result.team_name||row.team_name,events_json:JSON.stringify(result.events),source_meta_json:JSON.stringify(result.meta),sync_status:result.status,sync_error:result.error,last_sync_at:result.complete?gsStamp(runtime.at):feed.last_sync_at,updated_at:gsStamp(runtime.at),next_sync_at:result.next_at};
 return {...row,team_name:result.team_name||row.team_name,events_json:JSON.stringify(result.events),last_success_at:result.meta.discovery?.last_success_at||row.last_success_at,meta_json:JSON.stringify(meta)};
