async function gsBrowseRefresh(env,family,teamId,runtime=gsRuntime(),{force=false,live=false,day=gsStamp(runtime.at).slice(0,10),trackRecent=true,forceResults=force,context=false}={}){
 const stamp=gsStamp(runtime.at),token=crypto.randomUUID(),at=runtime.at;
 if(!live&&trackRecent)await env.DB.prepare('INSERT INTO gotsport_team_recent(family_key,team_id,last_opened_at) VALUES(?,?,?) ON CONFLICT(family_key,team_id) DO UPDATE SET last_opened_at=excluded.last_opened_at').bind(family,teamId,stamp).run();
 await env.DB.prepare('INSERT OR IGNORE INTO gotsport_history_cache(team_id) VALUES(?)').bind(teamId).run();
 const read=()=>env.DB.prepare('SELECT * FROM gotsport_history_cache WHERE team_id=?').bind(teamId).first();
 const lock=await env.DB.prepare('UPDATE gotsport_history_cache SET lease_token=?,lease_until=? WHERE team_id=? AND lease_until<=? AND retry_at<=?').bind(token,at+30000,teamId,at,at).run();
 if(!lock.meta?.changes)return (context?gsContextSnapshot:gsBrowseSnapshot)(await read(),day);
 let row=await read();
 try{
  if(context){row=await gsRefreshDashboard(env,row,teamId,runtime);}else{
  const stale=!row.last_success_at||at-Date.parse(row.last_success_at)>=GOTSPORT_HISTORY_FRESH_MS;
  if(!live&&(force||stale)){
   const profile=await gsTeamProfile(env,teamId,runtime);
   if(gsId(profile?.id)!==teamId||!profile.name)throw gsFail('GotSport did not confirm the requested team.','gotsport_team_identity');
   const result=gsDiscover(await gsFetchJson(`/teams/${teamId}/matches`,{},runtime),teamId);
   row={...row,team_name:gsDisplayName(profile.team_name||profile.name||result.team_name,profile.club_name),events_json:JSON.stringify(result.matches),last_success_at:stamp,meta_json:JSON.stringify({...safeJsonParse(row.meta_json,{}),profile:{id:teamId,name:profile.name||profile.team_name,club_name:profile.club_name,logo:gsLogoPath(profile.logo||profile.image||profile.team_logo_url_full),next_at:profile.next_at}}),results_checked_at:null};
  }else if(forceResults||at-Date.parse(row.results_checked_at||row.last_success_at||0)>=GOTSPORT_SCORE_CHECK_MS){
   const result=await gsBrowseRecent(env,row,runtime,day,forceResults);row={...row,events_json:JSON.stringify(result.events),meta_json:JSON.stringify(result.meta),results_checked_at:result.checked?gsStamp(result.checked):row.results_checked_at};
  }
  }
  await env.DB.prepare('UPDATE gotsport_history_cache SET team_name=?,events_json=?,last_success_at=?,meta_json=?,results_checked_at=?,sync_error=NULL,retry_at=0,lease_token=NULL,lease_until=0 WHERE team_id=? AND lease_token=?').bind(row.team_name,row.events_json,row.last_success_at,row.meta_json,row.results_checked_at||null,teamId,token).run();
 }catch(error){await env.DB.prepare('UPDATE gotsport_history_cache SET sync_error=?,retry_at=?,lease_token=NULL,lease_until=0 WHERE team_id=? AND lease_token=?').bind(clean(error?.message)||'GotSport update failed.',at+Math.max(GOTSPORT_SCORE_CHECK_MS,Number(error.retry_after_ms)||0),teamId,token).run();}
 return (context?gsContextSnapshot:gsBrowseSnapshot)(await read(),day);
}
async function handleTeamBrowse(request,env,url){
  const access=await requireViewer(request,env),family=clean(url.searchParams.get('key'));
  if(!keyOk(family))throw new ApiError('Missing team key.',400);
  requireDatasetFamily(access,family);
  if(!await env.DB.prepare('SELECT family_key FROM app_datasets WHERE family_key=?').bind(family).first())throw new ApiError('Team not found.',404);
  const path=url.pathname;
  if(path==='/api/gotsport/teams/search'&&request.method==='GET'){
    await enforceRateLimit(env,'gotsport-search:'+family,30,60000);
    return json(await gsSearchWithDiagnostics(env,family,url.searchParams));
  }
  if(path==='/api/gotsport/teams/recent'&&request.method==='GET'){
    const rows=await env.DB.prepare('SELECT r.team_id,c.team_name,c.last_success_at FROM gotsport_team_recent r JOIN gotsport_history_cache c ON c.team_id=r.team_id WHERE r.family_key=? ORDER BY r.last_opened_at DESC LIMIT 30').bind(family).all();
    return json({states:GOTSPORT_SEARCH_STATES,teams:(rows.results||[]).map(r=>({team_id:r.team_id,name:r.team_name||'GotSport team '+r.team_id,last_success_at:r.last_success_at}))});
  }
  const day=gsBrowseDay(url.searchParams.get('day')),teamId=gsId(url.searchParams.get('team_id'));if(!teamId)throw new ApiError('Invalid GotSport team.',400);
  if(path==='/api/gotsport/teams/context'&&['GET','POST'].includes(request.method)){
    if(request.method==='POST'){await enforceRateLimit(env,'gotsport-browse:'+family,120,60000);return json(await gsBrowseRefresh(env,family,teamId,gsRuntime(),{context:true,day}));}
    const row=await env.DB.prepare('SELECT * FROM gotsport_history_cache WHERE team_id=?').bind(teamId).first();return json(row?gsContextSnapshot(row,day):{team_id:teamId,events:[],dashboard:null});
  }
  if(path==='/api/gotsport/teams/snapshot'&&request.method==='GET'){
    const row=await env.DB.prepare('SELECT * FROM gotsport_history_cache WHERE team_id=?').bind(teamId).first();
    return json(row?gsBrowseSnapshot(row,day):{team_id:teamId,events:[],last_success_at:null,next_check_ms:0});
  }
  if(['/api/gotsport/teams/refresh','/api/gotsport/teams/results'].includes(path)&&request.method==='POST'){
    await enforceRateLimit(env,'gotsport-browse:'+family,120,60000);
    return json(await gsBrowseRefresh(env,family,teamId,gsRuntime(),{force:url.searchParams.get('force')==='1',live:path.endsWith('/results'),day}));
  }
  throw new ApiError('Unknown team browsing request.',404);
}

