 return {key:`gs:${row.event_id}:${row.match_id}`,team_id:row.team_id,match,unavailable:!!row.checked_at&&newer&&!raw,error:row.sync_error?(safeJsonParse(row.sync_error,{}).message||'Game updates are delayed.'):null,last_success_at:row.checked_at?gsStamp(row.checked_at):null,retry_at:Number(row.retry_at)||0,updated_at:row.checked_at?gsStamp(row.checked_at):null};
