 const add=days[day];if(add){for(const key of ['rows_read','rows_written','queries'])out[key]+=add[key];for(const [name,values] of Object.entries(add.workloads)){const group=out.workloads[name]||={rows_read:0,rows_written:0,queries:0};for(const key of ['rows_read','rows_written','queries'])group[key]+=values[key];}}return out;
